let iosAudioPrimer=null,connectTimer=null,micPermissionStream=null,micMonitorTimer=null,micRecoveryAttempted=false,micSignalSeen=false;
const startButton=byId('startRealtime'),muteButton=byId('muteRealtime'),resetButton=byId('resetRealtime'),refreshButton=byId('refreshApp'),floatingEndButton=byId('floatingEndRealtime'),orb=byId('voiceOrb');
const defaultRealtimeNote='English or Japanese is fine—Jack keeps the learning target American English. Uses your ElevenLabs free minutes.';
const profileStorageKey='jack_private_profile_v1';
function createProfileId(){
  const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);
  return 'anon_'+Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('');
}
function getProfileId(){
  let value='';try{value=localStorage.getItem(profileStorageKey)||'';}catch{}
  if(!/^anon_[a-f0-9]{36}$/.test(value)){value=createProfileId();try{localStorage.setItem(profileStorageKey,value);}catch{}}
  return value;
}
const profileId=getProfileId();
function profileFetch(url,options={}){
  const headers=new Headers(options.headers||{});headers.set('x-jack-profile-id',profileId);
  return fetch(url,{...options,headers});
}
function safeDiagnostic(value){
  let text=typeof value==='string'?value:'';
  text=text.replace(/((?:xi-api-key|api[_-]?key|authorization)\s*[:=]\s*)([^\s,;}]+)/gi,'$1[REDACTED]');
  text=text.replace(/\b(?:sk|xi)[_-][A-Za-z0-9_-]{12,}\b/g,'[REDACTED]');
  return text.slice(0,1600);
}
function errorDetail(error){
  if(error instanceof Error){
    const cause=error.cause?(typeof error.cause==='string'?error.cause:JSON.stringify(error.cause)):'';
    return safeDiagnostic(error.message+(cause?' | Cause: '+cause:''));
  }
  try{return safeDiagnostic(typeof error==='string'?error:JSON.stringify(error));}catch{return 'Unknown realtime connection error.';}
}
async function readRealtimeResponse(response){
  const raw=await response.text();let data={};
  try{data=raw?JSON.parse(raw):{};}catch{data={error:raw||'Unreadable server response.'};}
  if(!response.ok){
    const serverText=data?.error||data?.message||raw||'Realtime voice could not start.';
    const metadata=[data?.code&&'code='+data.code,data?.stage&&'stage='+data.stage,data?.providerStatus&&'ElevenLabs HTTP '+data.providerStatus,data?.providerMessage&&data.providerMessage].filter(Boolean).join(' | ');
    const error=new Error('HTTP '+response.status+(response.statusText?' '+response.statusText:'')+': '+serverText+(metadata?' | '+metadata:''));
    error.status=response.status;error.server=data;throw error;
  }
  return data;
}
